import{_ as e,o as t,c as i,a2 as n}from"./chunks/framework.EUByU7Iq.js";const p=JSON.parse('{"title":"第十三章 宅基地使用权","description":"","frontmatter":{"title":"第十三章 宅基地使用权","date":"2021-02-16T00:00:00.000Z","categories":["法律","民法典"],"tags":["法律","民法典"]},"headers":[],"relativePath":"blogs/CC/disanfenbian：yongyiwuquan（dishisanzhang：zhaijidishiyongquan）.md","filePath":"blogs/CC/第三分编：用益物权（第十三章：宅基地使用权）.md"}'),_={name:"blogs/CC/disanfenbian：yongyiwuquan（dishisanzhang：zhaijidishiyongquan）.md"};function o(r,a,s,d,h,l){return t(),i("div",null,[...a[0]||(a[0]=[n('<h3 id="第三百六十二条" tabindex="-1">第三百六十二条 <a class="header-anchor" href="#第三百六十二条" aria-label="Permalink to &quot;第三百六十二条&quot;">​</a></h3><p>宅基地使用权人依法对集体所有的土地享有占有和使用的权利，有权依法利用该土地建造住宅及其附属设施。</p><h3 id="第三百六十三条" tabindex="-1">第三百六十三条 <a class="header-anchor" href="#第三百六十三条" aria-label="Permalink to &quot;第三百六十三条&quot;">​</a></h3><p>宅基地使用权的取得、行使和转让，适用土地管理的法律和国家有关规定。</p><h3 id="第三百六十四条" tabindex="-1">第三百六十四条 <a class="header-anchor" href="#第三百六十四条" aria-label="Permalink to &quot;第三百六十四条&quot;">​</a></h3><p>宅基地因自然灾害等原因灭失的，宅基地使用权消灭。对失去宅基地的村民，应当依法重新分配宅基地。</p><h3 id="第三百六十五条" tabindex="-1">第三百六十五条 <a class="header-anchor" href="#第三百六十五条" aria-label="Permalink to &quot;第三百六十五条&quot;">​</a></h3><p>已经登记的宅基地使用权转让或者消灭的，应当及时办理变更登记或者注销登记。</p>',8)])])}const u=e(_,[["render",o]]);export{p as __pageData,u as default};
